import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    cnt = 0
    for i in range(1, n - 1):
        if (a[i] > a[i - 1] and a[i] > a[i + 1]) or (a[i] < a[i - 1] and a[i] < a[i + 1]):
            cnt += 1
    print(cnt)

if __name__ == "__main__":
    solve()
